import java.util.*;

class Solution {
  public List<String> findAllConcatenatedWordsInADict(String[] words) {
    Set<String> dict = new HashSet<>(Arrays.asList(words));
    List<String> ans = new ArrayList<>();
    for (String w : words) {
      int n = w.length();
      if (n == 0) continue;
      boolean[] dp = new boolean[n + 1];
      dp[0] = true;
      for (int j = 1; j <= n; j++)
        for (int i = 0; i < j && !dp[j]; i++)
          // a piece may not be the whole word itself
          if (dp[i] && (j - i) < n && dict.contains(w.substring(i, j))) dp[j] = true;
      if (dp[n]) ans.add(w);
    }
    return ans;
  }
}
